def build_synth_dll(dll_name, exports, base, stub_alloc, explicit_ordinals=None):
    """Builds a synthetic PE32+ DLL image with an EAT at `base`.
    stub_alloc(dll, funcname) -> stub address (must be > base, within 4GB).
    explicit_ordinals: optional {name: ordinal} to honor fixed ordinals (e.g. ws2_32)."""
    exports = sorted(set(exports))
    N = len(exports)
    if explicit_ordinals:
        exports = sorted(set(exports) | set(explicit_ordinals.keys()))
        N = len(exports)
        max_ord = max(explicit_ordinals.values())
        total_funcs = max(max_ord + 1, N)
        # assign each name a slot (ordinal index)
        used = set(explicit_ordinals.values())
        name_slot = {}
        for nm in exports:
            if nm in explicit_ordinals:
                name_slot[nm] = explicit_ordinals[nm]
        free_iter = (i for i in range(total_funcs) if i not in used)
        for nm in exports:
            if nm not in name_slot:
                name_slot[nm] = next(free_iter)
    else:
        total_funcs = N
        name_slot = {nm: i for i, nm in enumerate(exports)}
    # --- layout (RVA) ---
    HDR = 0x1000                 # headers page
    EAT = 0x1000                 # export directory at 0x1000
    FUNC_ARR = 0x1028            # total_funcs dwords
    NAME_ARR = 0x1028 + (total_funcs * 4 + 15) & ~15
    ORD_ARR = NAME_ARR + (N * 4 + 15) & ~15
    STRINGS = ORD_ARR + (N * 2 + 15) & ~15
    # strings
    str_blob = b''
    str_rvas = []
    for name in exports:
        b = name.encode('ascii') + b'\x00'
        str_rvas.append(STRINGS + len(str_blob))
        str_blob += b
    dll_name_str_rva = STRINGS + len(str_blob)
    str_blob += dll_name.encode('ascii') + b'\x00'
    IMG_SIZE = (STRINGS + len(str_blob) + 0xFFF) & ~0xFFF
    if IMG_SIZE < 0x2000: IMG_SIZE = 0x2000
    HEADER_IMAGE_SIZE = 0x100000   # claim the whole 1MB slot (so API stubs at +0x8000 pass module-range checks)

    img = bytearray(IMG_SIZE)
    # DOS header
    img[0:2] = b'MZ'
    struct.pack_into('<I', img, 0x3C, 0x40)
    # PE header at 0x40
    pe_off = 0x40
    img[pe_off:pe_off+4] = b'PE\x00\x00'
    # COFF
    struct.pack_into('<HHIIIHH', img, pe_off+4,
                     0x8664,      # Machine AMD64
                     1,           # NumberOfSections
                     0x60000000,  # TimeDateStamp
                     0, 0,        # symbols
                     0xF0,        # SizeOfOptionalHeader
                     0x2022)      # Characteristics: DLL|EXEC|READ
    # Optional header PE32+
    oh = pe_off + 24
    struct.pack_into('<HBBIIIII', img, oh,
                     0x20B, 14, 0, 0x8000, 0x4000, 0,
                     EAT, 0x1000)
    struct.pack_into('<QII', img, oh+0x18, base, 0x1000, 0x200)
    struct.pack_into('<HHHHHHI', img, oh+0x28,
                     6, 2, 0, 0, 6, 2, 0)   # OS/image/subsys versions + Win32Ver
    struct.pack_into('<IIIHHQQQQII', img, oh+0x38,
                     HEADER_IMAGE_SIZE, 0x1000, 0,   # SizeOfImage, SizeOfHeaders, CheckSum
                     3, 0x160,              # Subsystem=CONSOLE, DllCharacteristics
                     0x100000, 0x10000, 0x100000, 0x10000,  # stack/heap
                     0, 16)                 # LoaderFlags, NumberOfRvaAndSizes
    # DataDirectory[0] = export
    struct.pack_into('<II', img, oh+0x70, EAT, 40)
    # section table at oh+0xF0
    st = oh + 0xF0
    img[st:st+8] = b'.eda1\x00\x00\x00'
    struct.pack_into('<IIIIIIHHI', img, st+8,
                     HEADER_IMAGE_SIZE - 0x1000,  # VirtualSize (covers stub area)
                     0x1000,              # VirtualAddress
                     IMG_SIZE - 0x1000,  # SizeOfRawData
                     0x1000,              # PointerToRawData
                     0, 0, 0, 0,
                     0x60000020)          # EXEC|READ|CODE
    # export directory
    struct.pack_into('<IIHHIIIIIII', img, EAT,
                     0, 0x60000000, 0, 0,
                     dll_name_str_rva,    # Name RVA
                     1,                   # OrdinalBase
                     total_funcs, N,      # NumberOfFunctions / NumberOfNames
                     FUNC_ARR, NAME_ARR, ORD_ARR)
    # stubs + arrays
    func_rvas = {}
    default_stub = stub_alloc(dll_name, '_ordinal_pad_')
    for nm in exports:
        stub = stub_alloc(dll_name, nm)
        rva = stub - base
        assert 0 < rva < 0xFFFFFFFF, f"stub {hex(stub)} out of range for base {hex(base)}"
        func_rvas[name_slot[nm]] = rva
    default_rva = default_stub - base
    for i in range(total_funcs):
        struct.pack_into('<I', img, FUNC_ARR + 4*i, func_rvas.get(i, default_rva))
    for i, nm in enumerate(exports):
        struct.pack_into('<I', img, NAME_ARR + 4*i, str_rvas[i])
        struct.pack_into('<H', img, ORD_ARR + 2*i, name_slot[nm])
    img[STRINGS:STRINGS+len(str_blob)] = str_blob
    WRITABLE = 0x10000  # only write the first 64KB; the rest of the 1MB slot hosts API stubs
    return bytes(img[:WRITABLE]), {'base': base, 'func_arr_rva': FUNC_ARR, 'func_arr_off': base + FUNC_ARR,
                        'names': exports, 'eat_rva': EAT, 'image_size': IMG_SIZE}

