# ---------------- auto-repair: extra exports discovered iteratively ----------------
# File format: one "dllname|exportname" per line. Merged by ensure_synth at build time.
EXTRA_EXPORTS_FILE = '/home/z/my-project/scripts/extra_exports.txt'

def load_extra_exports():
    import os
    out = {}
    try:
        with open(EXTRA_EXPORTS_FILE) as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#') or '|' not in line:
                    continue
                dll, name = line.split('|', 1)
                out.setdefault(dll.strip().lower(), []).append(name.strip())
    except FileNotFoundError:
        pass
    return out
